    for (std::size_t c = 0; c < grid[1].size(); ++c) {
        grid[1][c] = 1;
    }
    for (std::size_t r = 0; r < grid.size(); ++r) {
        grid[r][2] = 1;
    }

    for (std::size_t r = 0; r < grid.size(); ++r) {
        for (std::size_t c = 0; c < grid[r].size(); ++c) {
            if (c > 0) {
                std::cout << ' ';
            }
            std::cout << grid[r][c];
        }
        std::cout << '\n';
    }
    std::cout << "Rows: " << grid.size() << ", columns: " << grid[0].size() << '\n';

    const std::vector<std::vector<int>> triangle = {{1}, {1, 1}, {1, 2, 1}};
    for (const auto& row : triangle) {
        std::cout << "Size " << row.size() << ':';
        for (int x : row) {
            std::cout << ' ' << x;
        }
        std::cout << '\n';
    }
    return 0;
}

